    selectedBoxStyle?: ChartBrushProps["selectedBoxStyle"];
    initialSelection?: ChartBrushProps["initialSelection"];
    selection?: ChartBrushProps["selection"];
    useWindowMoveEvents?: ChartBrushProps["useWindowMoveEvents"];
