const ChartBrushInner = memo(function ChartBrushInner({ brushDirection = "horizontal", selectedBoxStyle, initialSelection, selection, useWindowMoveEvents = true, xScale, yScale, innerWidth, innerHeight, margin, onBrushPreview, onBrushCommit, blurPx, fadeOuterEdges, selectionPattern, }: ChartBrushInnerProps) {
